 	msg.Data = resp.Message.Data
 	msg.Attributes = resp.Message.Attributes
 	msg.ID = resp.Message.MessageId
 	msg.PublishTime = pubTime
 	msg.DeliveryAttempt = deliveryAttempt
 	msg.OrderingKey = resp.Message.OrderingKey
